const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v).toLocaleString('zh-CN');
export function issueDetail(w){
 if(!w.issue_facets.length&&!w.issue_alternatives?.length)return '';
 return `<section class="detail-section issue-detail"><h3>细分问题与情节依据</h3>${w.issue_evidence_notes?.length?`<div class="issue-identity-note"><strong>本轮资料阅读范围</strong>${w.issue_evidence_notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}${w.knowledge?.corrections?.length?`<div class="issue-identity-note"><strong>分析更正记录</strong>${w.knowledge.corrections.map(c=>`<p>${esc(c.correction_note.reason)}</p><details><summary>查看更正前的误读及依据</summary><p>${esc(c.correction_note.old_claim)}</p><p>${esc(c.correction_note.source_scope)}</p>${c.sources.map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">查看所读材料 ↗</a>`).join('')}</details>`).join('')}</div>`:''}<p class="issue-evidence-label">已有知识补充 · 待独立核对</p>${w.knowledge_identity_notes?.length?`<div class="issue-identity-note"><strong>分析对象与题名备注</strong>${w.knowledge_identity_notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}<div class="issue-facet-cards">${w.issue_facets.map(f=>`<article><button class="tag" data-filter="facet" data-value="${esc(f.label)}">${esc(f.label)} ↗</button><h4>${esc(f.question)}</h4><p><strong>情节依据：</strong>${esc(f.basis)}</p></article>`).join('')}</div>${w.issue_alternatives?.length?`<details><summary>补充的核心问题解释（保留原分析）</summary>${w.issue_alternatives.map(a=>`<p>${esc(a.value)}</p>`).join('')}</details>`:''}<p class="issue-scope">这些是可修订的文学解释。依据包括已有知识及逐批说明的已读资料，尚未完成逐项独立核验；每项原记录与补充批次均保留。</p></section>`;
}
export function renderIssueExplorer(container,works){
 const analyzed=works.filter(w=>w.issue_analysis_status!=='missing'),withFacets=works.filter(w=>w.issue_facets.length),candidates=works.filter(w=>w.issue_analysis_status==='missing'&&w.topics.length);
 const labels=new Map();
 for(const w of works)for(const label of new Set(w.issue_facets.map(f=>f.label)))labels.set(label,(labels.get(label)||0)+1);
 const facets=[...labels].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'zh-CN'));
 const buttons=items=>items.map(([label,count])=>`<button data-filter="facet" data-value="${esc(label)}">${esc(label)} <small>${num(count)}</small></button>`).join('');
 container.innerHTML=`<section class="issue-overview"><div class="issue-overview-heading"><div><span class="eyebrow">WORKS / QUESTIONS / EVIDENCE</span><h3>从分类标签走进作品的问题</h3></div><a href="https://raw.githubusercontent.com/changkun/scifi-exploration/3fddc4f7d3b4c9723fc7274ec1f86bdf9c348caf/dist/assets/issue-analysis.json.gz" download>下载逐项分析 ↓</a></div><p>当前筛选 ${num(works.length)} 条：<strong>${num(analyzed.length)} 条有核心问题分析</strong>，${num(candidates.length)} 条只有分类候选；${num(works.length-analyzed.length)} 条分析尚未补充。已有细分分析 ${num(withFacets.length)} 条。缺口表示尚未整理进数据库。</p><div class="issue-actions"><button data-filter="issueStatus" data-value="analyzed">浏览已有作品分析 →</button><button data-filter="issueStatus" data-value="missing">浏览分析缺口 →</button></div><h4>细分议题 · ${num(facets.length)} 个原始分析标签</h4><p class="issue-scope">点击按具体问题筛选，保留当前年代与其他条件。相近标签暂时分别保留，避免抹掉细微差别；每条作品记录在同一标签下只计一次；尚未可靠合并的同名实体分别保留。</p><div class="issue-facet-cloud">${buttons(facets.slice(0,48))||'<p>当前条件下尚无细分问题记录。</p>'}</div>${facets.length>48?`<details class="issue-more"><summary>展开其余 ${num(facets.length-48)} 个细分议题</summary><div class="issue-facet-cloud">${buttons(facets.slice(48))}</div></details>`:''}${withFacets.length?`<h4>当前范围的作品分析</h4><div class="issue-example-grid">${withFacets.slice(0,6).map(w=>`<article><span>${esc(w.year_display)} · 知识补充待核</span><h4><button data-work="${esc(w.id)}">${esc(w.title_zh)}</button></h4><p>${esc(w.issue)}</p><div class="issue-example-tags">${w.issue_facets.map(f=>`<button data-filter="facet" data-value="${esc(f.label)}">${esc(f.label)}</button>`).join('')}</div><button class="browse-button" data-work="${esc(w.id)}">查看问题与情节依据 →</button></article>`).join('')}</div>`:''}</section>`;
}
